s=read('inventory/critic-battleclade-effective-source.json');cards={};sources=read('inventory/image-sources.json');assets=read('inventory/card-assets.json');manifest=[];activeTeam='Battleclade';activeRussian='БОЕВАЯ КЛАДА'
